svg.script:
// ============================================================
// 00 // BOOT CONSTANTS
// ============================================================
var CX = 960, CY = 540, FOC = 1050;
var ARENA_R = 6.5;
var T = 0;
var DL = [];
var PL = null, EN = null;
var PRE = [null, null];
var FLASH = 0, SHAKE = 0, BANT = 0, MVT = 0;
var SPARKS = [], RINGS = [], PROJ = [];
var SHARDS = [], TRAILS = [], PILLARS = [], AFTER = [];
var PADS = [], PDP = [[], [], [], []], PADN = 'KB';
var TOUCHON = false, TAP = false, IGN = 0;
var VI = 0;
var KEYS = {}, KEDGE = {};

var EL = {}, ELBUF = [], SR = [], SS = [];
var ACACHE = {};
var XL = 'http://www.w3.org/1999/xlink';
var ROT = [0, 1, 2];

function $(id){ return document.getElementById(id); }
function setTxt(el, s){ if(el && el.textContent !== s){ el.textContent = s; } }
function sA(el, attr, val){
  var k = el.id + '|' + attr;
  if(ACACHE[k] !== val){ ACACHE[k] = val; el.setAttribute(attr, val); }
}
function setBuf(el, v){
  if(el.getAttribute('href') !== v){
    el.setAttribute('href', v);
    try{ el.setAttributeNS(XL, 'xlink:href', v); }catch(e){}
  }
}
function kD(c){ return !!KEYS[c]; }
function kE(c){ return !!KEDGE[c]; }
function KSET(c, v){
  if(v && !KEYS[c]){ KEDGE[c] = true; }
  KEYS[c] = v;
  if(v){ try{ var a = audio(); if(a && a.state === 'suspended'){ a.resume(); } }catch(e){} }
}

var GAME = {
  state: 'title',
  mode: '1p',
  ei: 0,
  oppList: [],
  round: 1,
  plw: 0,
  enw: 0,
  timer: 60,
  introT: 0,
  koT: 0,
  nextT: 0,
  selT: 0,
  fightShown: false,
  paused: false,
  p1sel: 0, p2sel: 1, p1lock: false, p2lock: false
};

var FPS = { acc: 0, n: 0, low: false };

// ============================================================
// 01 // MATH
// ============================================================
function sub(a,b){ return [a[0]-b[0], a[1]-b[1], a[2]-b[2]]; }
function add(a,b){ return [a[0]+b[0], a[1]+b[1], a[2]+b[2]]; }
function mul(a,s){ return [a[0]*s, a[1]*s, a[2]*s]; }
function dot(a,b){ return a[0]*b[0] + a[1]*b[1] + a[2]*b[2]; }
function cross(a,b){
  return [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]];
}
function len(a){ return Math.sqrt(a[0]*a[0]+a[1]*a[1]+a[2]*a[2]); }
function nrm(a){ var l = len(a); if(l < 1e-6){ l = 1; } return [a[0]/l, a[1]/l, a[2]/l]; }
function L(a,b,t){ return a + (b-a)*t; }
function LZ(a,b,t){ return [L(a[0],b[0],t), L(a[1],b[1],t), L(a[2],b[2],t)]; }
function clamp(v,a,b){ return v < a ? a : (v > b ? b : v); }
function EO(t){ t = clamp(t,0,1); return 1 - (1-t)*(1-t); }
function EI(t){ t = clamp(t,0,1); return t*t; }
function EZ(t){ t = clamp(t,0,1); return t*t*(3-2*t); }
function rnd(a,b){ return a + Math.random()*(b-a); }
function mid(a,b,t){ t = (t === undefined) ? 0.5 : t;
  return [L(a[0],b[0],t), L(a[1],b[1],t), L(a[2],b[2],t)]; }

var CAM = { yaw: 0.6, pit: 0.30, dist: 9.8, tx: 0, ty: 1.2, tz: 0 };
var SHX = 0, SHY = 0;
var VIEWS = [
  { yaw: 0.60, pit: 0.30, dist: 9.8 },
  { yaw: 1.05, pit: 0.14, dist: 8.2 },
  { yaw: 0.35, pit: 0.52, dist: 11.6 },
  { yaw: 0.85, pit: 0.30, dist: 13.8 }
];

function proj(p){
  var dx = p[0]-CAM.tx, dy = p[1]-CAM.ty, dz = p[2]-CAM.tz;
  var cy = Math.cos(CAM.yaw), sy = Math.sin(CAM.yaw);
  var x1 = dx*cy - dz*sy;
  var z1 = dx*sy + dz*cy;
  var cp = Math.cos(CAM.pit), sp = Math.sin(CAM.pit);
  var y2 = dy*cp + z1*sp;
  var z2 = -dy*sp + z1*cp;
  var d = z2 + CAM.dist;
  if(d < 0.35){ d = 0.35; }
  return [CX + x1*FOC/d + SHX, CY - y2*FOC/d + SHY, d];
}

var vCY = 1, vSY = 0, vCP = 1, vSP = 0;
function cacheCamRot(){
  vCY = Math.cos(CAM.yaw); vSY = Math.sin(CAM.yaw);
  vCP = Math.cos(CAM.pit); vSP = Math.sin(CAM.pit);
}
function nvis(nx, ny, nz){
  var z1 = nx*vSY + nz*vCY;
  return (-ny*vSP + z1*vCP) < -0.02;
}

function segSeg(p1,q1,p2,q2){
  var d1 = sub(q1,p1), d2 = sub(q2,p2), r = sub(p1,p2);
  var a = dot(d1,d1), e = dot(d2,d2), f = dot(d2,r), s, t;
  if(a <= 1e-9 && e <= 1e-9){ return len(r); }
  if(a <= 1e-9){ s = 0; t = clamp(f/e,0,1); }
  else {
    var c = dot(d1,r);
    if(e <= 1e-9){ t = 0; s = clamp(-c/a,0,1); }
    else {
      var b = dot(d1,d2), den = a*e - b*b;
      s = den > 1e-9 ? clamp((b*f - c*e)/den, 0, 1) : 0;
      t = (b*s + f)/e;
      if(t < 0){ t = 0; s = clamp(-c/a,0,1); }
      else if(t > 1){ t = 1; s = clamp((b-c)/a,0,1); }
    }
  }
  var c1 = add(p1, mul(d1,s)), c2 = add(p2, mul(d2,t));
  return len(sub(c1,c2));
}

// ============================================================
// 02 // RENDERER PRIMITIVES
// ============================================================
function poly(pts, col, sw, op, fill, layer){
  var s = '', z = 0, i, p;
  for(i = 0; i < pts.length; i++){
    p = proj(pts[i]);
    s += (i ? 'L' : 'M') + p[0].toFixed(1) + ',' + p[1].toFixed(1);
    z += p[2];
  }
  DL.push({ l: layer, z: z/pts.length,
    s: '<path d="' + s + 'Z" fill="' + fill + '" stroke="' + col +
       '" stroke-width="' + sw + '" stroke-opacity="' + op +
       '" stroke-linejoin="round"/>' });
}

function pline(pts, col, sw, op, layer){
  var s = '', z = 0, i, p;
  for(i = 0; i < pts.length; i++){
    p = proj(pts[i]);
    s += (i ? 'L' : 'M') + p[0].toFixed(1) + ',' + p[1].toFixed(1);
    z += p[2];
  }
  DL.push({ l: layer, z: z/pts.length,
    s: '<path d="' + s + '" fill="none" stroke="' + col +
       '" stroke-width="' + sw + '" stroke-opacity="' + op +
       '" stroke-linecap="round"/>' });
}

function lineSeg(a, b, col, sw, op, layer){
  pline([a,b], col, sw, op, layer);
}

function boxSeg(a, b, u, v, wa, da, wb, db, col, caps){
  var dir = nrm(sub(b,a));
  var A1 = add(a, add(mul(u,-wa/2), mul(v,-da/2)));
  var A2 = add(a, add(mul(u, wa/2), mul(v,-da/2)));
  var A3 = add(a, add(mul(u, wa/2), mul(v, da/2)));
  var A4 = add(a, add(mul(u,-wa/2), mul(v, da/2)));
  var B1 = add(b, add(mul(u,-wb/2), mul(v,-db/2)));
  var B2 = add(b, add(mul(u, wb/2), mul(v,-db/2)));
  var B3 = add(b, add(mul(u, wb/2), mul(v, db/2)));
  var B4 = add(b, add(mul(u,-wb/2), mul(v, db/2)));
  if(nvis(-v[0],-v[1],-v[2])) poly([A1,A2,B2,B1], col, 1.7, 1, '#000', 2);
  if(nvis( u[0], u[1], u[2])) poly([A2,A3,B3,B2], col, 1.7, 1, '#000', 2);
  if(nvis( v[0], v[1], v[2])) poly([A3,A4,B4,B3], col, 1.7, 1, '#000', 2);
  if(nvis(-u[0],-u[1],-u[2])) poly([A4,A1,B1,B4], col, 1.7, 1, '#000', 2);
  if(caps){
    if(nvis(-dir[0],-dir[1],-dir[2])) poly([A1,A2,A3,A4], col, 1.7, 1, '#000', 2);
    if(nvis( dir[0], dir[1], dir[2])) poly([B1,B2,B3,B4], col, 1.7, 1, '#000', 2);
  }
}

function limbTaper(a, b, w1, w2, col){
  var d = sub(b, a);
  var l = len(d);
  if(l < 1e-5){ return; }
  var dir = mul(d, 1/l);
  var ref = Math.abs(dir[1]) > 0.92 ? [1,0,0] : [0,1,0];
  var u = nrm(cross(dir, ref));
  var v = nrm(cross(u, dir));
  boxSeg(a, b, u, v, w1, w1, w2, w2, col, false);
}

function boxCC3(c, u, v, w, sx, sy, sz, col){
  var C = [], i, su, sv, sw;
  for(i = 0; i < 8; i++){
    su = (i & 1) ? 1 : -1;
    sv = (i & 2) ? 1 : -1;
    sw = (i & 4) ? 1 : -1;
    C.push(add(c, add(add(mul(u, su*sx/2), mul(v, sv*sy/2)), mul(w, sw*sz/2))));
  }
  var F = [[0,1,5,4],[3,2,6,7],[0,1,2,3],[4,5,7,6],[0,2,6,4],[1,5,7,3]];
  var NX = [-v[0], v[0], -w[0], w[0], -u[0], u[0]];
  var NY = [-v[1], v[1], -w[1], w[1], -u[1], u[1]];
  var NZ = [-v[2], v[2], -w[2], w[2], -u[2], u[2]];
  for(i = 0; i < 6; i++){
    if(nvis(NX[i], NY[i], NZ[i])){
      var f = F[i];
      poly([C[f[0]], C[f[1]], C[f[2]], C[f[3]]], col, 1.7, 1, '#000', 2);
    }
  }
}

function tri(a, b, c, col){
  poly([a,b,c], col, 1.5, 1, '#000', 2);
}

function pyr(c, dir, h, bw, col){
  var ref = Math.abs(dir[1]) > 0.92 ? [1,0,0] : [0,1,0];
  var u = nrm(cross(dir, ref));
  var v = nrm(cross(u, dir));
  var ap = add(c, mul(dir, h));
  var B = [
    add(c, add(mul(u,-bw/2), mul(v,-bw/2))),
    add(c, add(mul(u, bw/2), mul(v,-bw/2))),
    add(c, add(mul(u, bw/2), mul(v, bw/2))),
    add(c, add(mul(u,-bw/2), mul(v, bw/2)))
  ];
  tri(B[0],B[1],ap,col); tri(B[1],B[2],ap,col);
  tri(B[2],B[3],ap,col); tri(B[3],B[0],ap,col);
}

function ringP(c, r, n, u, v, col, sw, op){
  var pts = [], i;
  for(i = 0; i < n; i++){
    var a = i/n*Math.PI*2;
    pts.push(add(c, add(mul(u, Math.cos(a)*r), mul(v, Math.sin(a)*r))));
  }
  poly(pts, col, sw, op, 'none', 2);
}

function fistBox(h, e, s, col){
  var d = nrm(sub(h, e));
  var u = nrm(cross(d, Math.abs(d[1]) > 0.93 ? [1,0,0] : [0,1,0]));
  var v = nrm(cross(u, d));
  boxCC3(h, u, v, d, s, s, s, col);
}

// triangular prism segment (polygon shard limb facet)
function triPrism(p0, p1, u, v, w0, w1, rot, col){
  function vv(p, w, a){
    return add(p, add(mul(u, Math.cos(a)*w), mul(v, Math.sin(a)*w)));
  }
  var A = rot, B = rot + 2.094, C = rot + 4.189;
  var q0 = [vv(p0, w0, A), vv(p0, w0, B), vv(p0, w0, C)];
  var q1 = [vv(p1, w1, A), vv(p1, w1, B), vv(p1, w1, C)];
  poly([q0[0], q0[1], q1[1], q1[0]], col, 1.5, 1, '#000', 2);
  poly([q0[1], q0[2], q1[2], q1[1]], col, 1.5, 1, '#000', 2);
  poly([q0[2], q0[0], q1[0], q1[2]], col, 1.5, 1, '#000', 2);
}

// ============================================================
// 03 // ARENA
// ============================================================
var HEX = [], HEXI = [], PYL = [], BPOLY = [];

function buildArena(){
  var s = 1.1, q, r, i, a, x, z;
  for(q = -6; q <= 6; q++){
    for(r = -6; r <= 6; r++){
      x = 1.5*s*q;
      z = Math.sqrt(3)*s*(r + q/2);
      if(Math.hypot(x, z) < ARENA_R + 0.4){
        var o = [];
        for(i = 0; i < 6; i++){
          a = Math.PI/3*i;
          o.push([x + Math.cos(a)*s, 0, z + Math.sin(a)*s]);
        }
        HEX.push(o);
        if(((q + r) % 3 + 3) % 3 === 0){
          var oi = [];
          for(i = 0; i < 6; i++){
            a = Math.PI/3*i;
            oi.push([x + Math.cos(a)*s*0.55, 0, z + Math.sin(a)*s*0.55]);
          }
          HEXI.push(oi);
        }
      }
    }
  }
  for(i = 0; i < 6; i++){
    a = Math.PI/3*i + Math.PI/6;
    var px = Math.cos(a)*(ARENA_R + 0.32);
    var pz = Math.sin(a)*(ARENA_R + 0.32);
    PYL.push([px, 0, pz]);
    BPOLY.push([px, 0, pz]);
  }
}

function hexPts(cx, cz, r, rot){
  var p = [], i;
  for(i = 0; i < 6; i++){
    var a = Math.PI/3*i + (rot || 0);
    p.push([cx + Math.cos(a)*r, 0, cz + Math.sin(a)*r]);
  }
  return p;
}
function hexPts3(cx, cy, cz, r, rot){
  var p = [], i;
  for(i = 0; i < 6; i++){
    var a = Math.PI/3*i + (rot || 0);
    p.push([cx + Math.cos(a)*r, cy, cz + Math.sin(a)*r]);
  }
  return p;
}

function drawArena(){
  var i, j, a;
  for(i = 0; i < HEX.length; i++){ poly(HEX[i], '#0f5c2b', 1.1, 0.75, '#000', 0); }
  if(!FPS.low){
    for(i = 0; i < HEXI.length; i++){ poly(HEXI[i], '#0c3f1f', 0.8, 0.5, 'none', 0); }
  }
  poly(BPOLY, '#39ff6e', 2.5, 0.9, 'none', 0);
  var o = [];
  for(i = 0; i < 30; i++){
    a = i/30*Math.PI*2;
    o.push([Math.cos(a)*(ARENA_R + 1.1), 0, Math.sin(a)*(ARENA_R + 1.1)]);
  }
  poly(o, '#1f7a3d', 1.2, 0.5, 'none', 0);
  if(!FPS.low){
    var b = [];
    for(i = 0; i < 32; i++){
      a = i/32*Math.PI*2;
      b.push([Math.cos(a)*16, 0, Math.sin(a)*16]);
    }
    poly(b, '#0c3f1f', 1, 0.4, 'none', 0);
    for(i = 0; i < 12; i++){
      a = i/12*Math.PI*2 + 0.13;
      var x = Math.cos(a)*14, z = Math.sin(a)*14;
      lineSeg([x,0,z], [x,4.2,z], '#0f5c2b', 1.5, 0.5, 0);
    }
  }
  poly(hexPts(0,0,1.35,Math.PI/6), '#1f7a3d', 1.4, 0.8, 'none', 0);
  poly(hexPts(0,0,0.8,0), '#1f7a3d', 1.2, 0.8, 'none', 0);
  poly(hexPts(0,0,0.35,Math.PI/6), '#39ff6e', 1.2, 0.9, 'none', 0);
  for(i = 0; i < 3; i++){
    a = Math.PI/3*i + Math.PI/6;
    lineSeg([Math.cos(a)*0.8,0,Math.sin(a)*0.8],
            [Math.cos(a)*1.35,0,Math.sin(a)*1.35], '#1f7a3d', 1, 0.7, 0);
  }
  for(i = 0; i < 6; i++){
    lineSeg([0,0,0], [PYL[i][0],0,PYL[i][2]], '#0c3f1f', 0.8, 0.4, 0);
    var px = PYL[i][0], pz = PYL[i][2];
    boxCC3([px,1.4,pz], [1,0,0],[0,0,1],[0,1,0], 0.34, 0.34, 2.8, '#39ff6e');
    boxCC3([px,2.95,pz], [1,0,0],[0,0,1],[0,1,0], 0.52, 0.52, 0.26, '#39ff6e');
    lineSeg([px,3.1,pz], [px,4.0,pz], '#39ff6e', 2, 0.7, 0);
  }
  if(PL && GAME.state === 'fight' && PL.me >= 35){
    var rr = 0.55 + Math.sin(T*7)*0.12;
    poly(hexPts(PL.x, PL.z, rr, Math.PI/6 + T), '#b6ffd0', 1.6, 0.55, 'none', 0);
  }
  if(EN && GAME.state === 'fight' && EN.me >= 35){
    var rr2 = 0.55 + Math.sin(T*7 + 2)*0.12;
    poly(hexPts(EN.x, EN.z, rr2, Math.PI/6 + T), EN.R.col, 1.6, 0.55, 'none', 0);
  }
}

// ============================================================
// 04 // RIGS : muscular humanoid male proportions + identity kit
// ============================================================
function baseRig(){
  return {
    scale: 1,
    chestW: 1.06, chestD: 0.62, chestH: 0.36,
    abdW: 0.66, abdD: 0.52,
    pelW: 0.86, pelH: 0.44, pelD: 0.54,
    headW: 0.34, headH: 0.40, headD: 0.37,
    shX: 0.78, shY: 2.18,
    elX: 0.88, elY: 1.60, elZ: 0.18,
    haX: 0.68, haY: 1.12, haZ: 0.36,
    ua: 0.34, la: 0.28, bicep: 0.40, fore: 0.31, fistW: 0.30,
    neckW: 0.20, trapW: 0.24,
    hipY: 1.08, hpX: 0.28,
    knX: 0.30, knY: 0.55, knZ: 0.04,
    th1: 0.44, th2: 0.32, ca1: 0.30, ca2: 0.22, calf: 0.34,
    ftX: 0.32, footW: 0.30, footD: 0.58,
    padW: 0.50,
    hunch: 0, hover: 0, jaw: 0,
    spikes: 0, gear: 0, crest: 0, pauldron: 0, slab: 0, horns: 0,
    halo: 0, wings: 0, ant: 0, spine: 0, fangs: 0, claws: 0,
    tail: 0, blade: 0, thruster: 0,
    polyArm: 0, beastLeg: 0, mane: 0, belt: 0, kneecap: 0, armSpikes: 0,
    sigil: 'hex',
    hurtR: 0.20,
    name: 'VANGUARD-01', col: '#39ff6e', ai: 'player',
    hp: 100, dmgMul: 1, speed: 4.3, pref: 1.8, reach: 2.25, cool: 0.9
  };
}

var ROSTER = [
  // GEAROX : yellow mass monster bodybuilder
  { name:'GEAROX', col:'#ffd23f', hp:125, dmg:1.15, spd:0.74, pref:2.0, reach:2.35, cool:1.15, ai:'brute', scale:1.15,
    edit:function(R){
      R.chestW *= 1.55; R.chestD *= 1.30; R.chestH *= 1.35;
      R.abdW *= 1.20; R.pelW *= 1.12;
      R.shX *= 1.20; R.shY *= 1.03; R.padW *= 1.55;
      R.ua *= 1.50; R.bicep *= 1.60; R.la *= 1.35; R.fore *= 1.40; R.fistW *= 1.80;
      R.th1 *= 1.35; R.th2 *= 1.25; R.ca1 *= 1.15; R.calf *= 1.30;
      R.neckW *= 1.50; R.trapW *= 1.65;
      R.headW *= 0.90; R.headH *= 0.92;
      R.hurtR *= 1.18;
      R.spikes = 1; R.gear = 1; R.armSpikes = 1; R.kneecap = 1;
      R.sigil = 'gear';
    }},
  // VERMIL : red lean duelist with polygon shard arms
  { name:'VERMIL', col:'#ff4444', hp:100, dmg:1.0, spd:1.07, pref:1.85, reach:2.40, cool:0.7, ai:'blade', scale:1.02,
    edit:function(R){
      R.chestW *= 0.95; R.chestD *= 0.95; R.abdW *= 0.80; R.pelW *= 0.86;
      R.shX *= 1.06; R.padW *= 0.72;
      R.polyArm = 1; R.la *= 0.55; R.fistW *= 0.40;
      R.th1 *= 0.85; R.th2 *= 0.80; R.ca1 *= 0.78; R.calf *= 0.80;
      R.neckW *= 0.90; R.trapW *= 0.70;
      R.crest = 1; R.belt = 1;
      R.sigil = 'strap';
    }},
  // KOLOSS : blue slab armored powerlifter
  { name:'KOLOSS', col:'#4fc3ff', hp:145, dmg:1.2, spd:0.65, pref:2.15, reach:2.40, cool:1.3, ai:'tank', scale:1.12,
    edit:function(R){
      R.chestW *= 1.45; R.chestD *= 1.35; R.chestH *= 1.20;
      R.abdW *= 1.28; R.pelW *= 1.16;
      R.shX *= 1.28; R.padW *= 1.75;
      R.ua *= 1.35; R.bicep *= 1.30; R.la *= 1.30; R.fore *= 1.30; R.fistW *= 1.35;
      R.th1 *= 1.30; R.th2 *= 1.25; R.ca1 *= 1.25; R.calf *= 1.30;
      R.neckW *= 1.45; R.trapW *= 1.50;
      R.hurtR *= 1.20;
      R.pauldron = 1; R.slab = 1; R.horns = 1; R.kneecap = 1;
      R.sigil = 'slab';
    }},
  // GHOST-9 : white hovering phantom with polygon shard arms
  { name:'GHOST-9', col:'#e8f6ff', hp:90, dmg:0.9, spd:1.19, pref:2.0, reach:2.15, cool:0.7, ai:'ghost', scale:0.99,
    edit:function(R){
      R.chestW *= 0.80; R.chestD *= 0.85; R.abdW *= 0.72; R.pelW *= 0.80;
      R.shX *= 0.98; R.padW *= 0.66;
      R.polyArm = 1; R.ua *= 0.85; R.la *= 0.50; R.fistW *= 0.35;
      R.th1 *= 0.70; R.th2 *= 0.65; R.ca1 *= 0.60; R.calf *= 0.62;
      R.neckW *= 0.80; R.trapW *= 0.55;
      R.headW *= 1.28; R.headH *= 1.30;
      R.hover = 0.55; R.hurtR *= 0.85;
      R.halo = 1; R.wings = 1; R.ant = 1;
      R.sigil = 'diamond';
    }},
  // EMBERFANG : orange digitigrade apex beast
  { name:'EMBERFANG', col:'#ff9a3d', hp:112, dmg:1.05, spd:1.05, pref:1.65, reach:2.25, cool:0.8, ai:'beast', scale:1.06,
    edit:function(R){
      R.hunch = 1; R.chestW *= 1.22; R.chestD *= 1.12; R.chestH *= 1.10; R.abdW *= 1.05;
      R.shX *= 1.12; R.padW *= 1.05;
      R.ua *= 1.12; R.bicep *= 1.20; R.la *= 1.15; R.fore *= 1.15; R.fistW *= 1.05;
      R.beastLeg = 1;
      R.th1 *= 1.30; R.th2 *= 1.10; R.ca1 *= 0.90; R.calf *= 0.85;
      R.ftX *= 1.20; R.footW *= 1.20; R.footD *= 0.75;
      R.neckW *= 1.20; R.trapW *= 1.10;
      R.headW *= 0.95; R.headH *= 0.82;
      R.hurtR *= 1.05;
      R.jaw = 1; R.spine = 1; R.fangs = 1; R.claws = 1; R.tail = 1; R.mane = 1;
      R.sigil = 'scars';
    }}
];

var FULLROSTER = [{ name: 'VANGUARD-01', col: '#39ff6e' }].concat(
  ROSTER.map(function(r){ return { name: r.name, col: r.col }; })
);
var FULLSTAT = [{ hp: 100, dmg: 1.0, spd: 1.0 }].concat(
  ROSTER.map(function(r){ return { hp: r.hp, dmg: r.dmg, spd: r.spd }; })
);

// [RT signature special, LT special]
var CHARSPEC = {
  'VANGUARD-01': ['sp1', 'sp2'],
  'GEAROX':      ['g_slam', 'g_rush'],
  'VERMIL':      ['v_cross', 'v_dance'],
  'KOLOSS':      ['k_stomp', 'k_wall'],
  'GHOST-9':     ['gh_blast', 'gh_blink'],
  'EMBERFANG':   ['e_pounce', 'e_burst']
};

// per character normal move chains (distinct fighting styles)
var CHAIN = {
  'VANGUARD-01': { P: ['jab', 'cross'],  K: ['kick'],   J: ['jumpatk'] },
  'GEAROX':      { P: ['g_jab', 'g_cross'], K: ['g_kick'], J: ['jumpatk'] },
  'VERMIL':      { P: ['v_jab', 'v_cross'], K: ['v_kick'], J: ['jumpatk'] },
  'KOLOSS':      { P: ['k_jab', 'k_cross'], K: ['k_kick'], J: ['jumpatk'] },
  'GHOST-9':     { P: ['gh_jab', 'gh_cross'], K: ['gh_kick'], J: ['jumpatk'] },
  'EMBERFANG':   { P: ['e_jab', 'e_cross'], K: ['e_kick'], J: ['jumpatk'] }
};

var SCALED = ['chestW','chestD','chestH','abdW','abdD','pelW','pelH','pelD',
  'headW','headH','headD','shX','shY','elX','elY','elZ','haX','haY','haZ',
  'ua','la','bicep','fore','fistW','neckW','trapW','hipY','hpX','knX','knY','knZ',
  'th1','th2','ca1','ca2','calf','ftX','footW','footD','padW','hurtR'];

function buildRig(name){
  var R = baseRig();
  if(name !== 'PLAYER'){
    var i, D;
    for(i = 0; i < ROSTER.length; i++){ if(ROSTER[i].name === name){ D = ROSTER[i]; } }
    for(var k = 0; k < SCALED.length; k++){ R[SCALED[k]] *= D.scale; }
    D.edit(R);
    R.name = D.name; R.col = D.col; R.ai = D.ai;
    R.hp = D.hp; R.dmgMul = D.dmg;
    R.speed = 4.3 * D.spd;
    R.pref = D.pref; R.reach = D.reach; R.cool = D.cool;
  }
  R.thruster = (name === 'PLAYER') ? 1 : 0;
  R.uchY = R.hipY + (R.shY - R.hipY)*0.94;
  R.chY = R.hipY + (R.shY - R.hipY)*0.60;
  return R;
}

function buildRigFor(selIdx){
  return buildRig(selIdx === 0 ? 'PLAYER' : FULLROSTER[selIdx].name);
}

// ============================================================
// 05 // POSE SYSTEM
// ============================================================
function basePose(f){
  var R = f.R;
  var br = Math.sin(T*3.0 + f.phase)*0.02;
  var p = {
    pel: [0, R.hipY, 0],
    chs: [0, R.chY + br, 0.02 + R.hunch*0.26],
    uch: [0, R.uchY + br*0.7, 0.03 + R.hunch*0.30],
    hed: [0, R.shY + 0.38 + R.hunch*(-0.10), 0.05 + R.hunch*0.42],
    shL: [-R.shX, R.shY, R.hunch*0.30],
    shR: [ R.shX, R.shY, R.hunch*0.30],
    elL: [-R.elX, R.elY, R.elZ + R.hunch*0.22],
    elR: [ R.elX, R.elY, R.elZ + R.hunch*0.22],
    haL: [-R.haX, R.haY, R.haZ + R.hunch*0.18],
    haR: [ R.haX, R.haY, R.haZ + R.hunch*0.18],
    hpL: [-R.hpX, R.hipY - 0.06, 0],
    hpR: [ R.hpX, R.hipY - 0.06, 0],
    knL: [-R.knX, R.knY, R.knZ],
    knR: [ R.knX, R.knY, R.knZ],
    ftL: [-R.ftX, 0.10, 0.06],
    ftR: [ R.ftX, 0.10, 0.06]
  };
  if(R.hover){
    var hs = Math.sin(T*2.8 + f.phase);
    p.pel[1] += R.hover;
    p.chs[1] += R.hover*0.9;
    p.uch[1] += R.hover*0.9;
    p.hed[1] += R.hover*0.8;
    p.knL[1] += R.hover*0.75 + hs*0.05;
    p.knR[1] += R.hover*0.75 - hs*0.05;
    p.ftL = [-R.ftX, R.hover*0.45 + hs*0.08, 0.14];
    p.ftR = [ R.ftX, R.hover*0.45 - hs*0.08, 0.14];
  }
  if(R.beastLeg){
    p.knL[1] += 0.14; p.knL[2] += 0.26;
    p.knR[1] += 0.14; p.knR[2] += 0.26;
    p.ftL[2] -= 0.06; p.ftR[2] -= 0.06;
  }
  return p;
}

function walkPose(f){
  var R = f.R;
  var p = basePose(f);
  var sp = Math.hypot(f.mv[0], f.mv[1]);
  var a = 0.45 * Math.min(1, sp);
  if(R.beastLeg){ a *= 1.35; }
  var sw = Math.sin(f.walkPh), cw = Math.cos(f.walkPh);
  p.ftL = [-R.ftX, 0.10 + Math.max(0,cw)*0.36*a, 0.06 + sw*a];
  p.knL = [-R.knX, R.knY + Math.max(0,cw)*0.18*a, R.knZ + sw*a*0.5];
  p.ftR = [ R.ftX, 0.10 + Math.max(0,-cw)*0.36*a, 0.06 - sw*a];
  p.knR = [ R.knX, R.knY + Math.max(0,-cw)*0.18*a, R.knZ - sw*a*0.5];
  if(R.beastLeg){
    p.knL[1] += 0.14; p.knL[2] += 0.26;
    p.knR[1] += 0.14; p.knR[2] += 0.26;
    p.ftL[2] -= 0.06; p.ftR[2] -= 0.06;
  }
  p.pel[1] += Math.abs(sw)*0.03 - 0.02;
  p.haL[2] = R.haZ - sw*0.14;
  p.haR[2] = R.haZ + sw*0.14;
  return p;
}

// ============================================================
// 06 // MOVE LIBRARY
//  Normal chains are built from parametric factories so every
//  fighter punches and kicks differently. RT specials each carry
//  dedicated VFX events (pillars, shards, trails, cracks, ghosts).
// ============================================================
function ringFX(c, col){ RINGS.push({ c: c, r: 0.3, l: 0.6, l0: 0.6, col: col }); }
function glyphFX(c, col, r){ RINGS.push({ c: c, r: r || 0.5, l: 0.75, l0: 0.75, col: col, g: 1 }); }

function clampPos(f){
  var rr = Math.hypot(f.x, f.z);
  if(rr > ARENA_R - 0.55){
    var s = (ARENA_R - 0.55)/rr;
    f.x *= s; f.z *= s;
  }
}

function radialHit(f, foe, dmg, r, kb){
  var d = Math.hypot(foe.x - f.x, foe.z - f.z);
  if(d < r && foe.state !== 'ko'){
    applyHit(f, foe, { dmg: dmg, kb: kb, tip: null });
  }
}

function spawnOrb(f, foe, opt){
  var ang = opt.spread || 0;
  var dir = nrm([foe.x - f.x, 0, foe.z - f.z]);
  var ca = Math.cos(ang), sa = Math.sin(ang);
  var dx = dir[0]*ca - dir[2]*sa;
  var dz = dir[0]*sa + dir[2]*ca;
  PROJ.push({
    p: [f.x + dx*0.6, opt.y || 1.5, f.z + dz*0.6],
    v: [dx*(opt.v||11), 0, dz*(opt.v||11)],
    r: opt.r || 0.22, col: opt.col, life: opt.life || 1.1,
    dmg: opt.dmg, own: f, kind: opt.kind || 'orb',
    seed: Math.random()*7, trail: opt.trail || 0
  });
}

function crackLine(x, z, ang, ln, col){
  var pts = [[x, 0.02, z]], a = ang, i;
  for(i = 1; i <= 4; i++){
    a += rnd(-0.4, 0.4);
    pts.push([x + Math.cos(a)*ln*i/4, 0.02, z + Math.sin(a)*ln*i/4]);
  }
  TRAILS.push({ pts: pts, col: col, life: 0.8, l0: 0.8, w: 2.2 });
}

function debris(x, z, col, n, pw){
  if(FPS.low){ n = Math.ceil(n/2); }
  for(var i = 0; i < n; i++){
    var a = rnd(0, Math.PI*2);
    SHARDS.push({
      p: [x + Math.cos(a)*rnd(0.1, 0.5), 0.25, z + Math.sin(a)*rnd(0.1, 0.5)],
      v: [Math.cos(a)*rnd(1.5, pw), rnd(3, 7.5), Math.sin(a)*rnd(1.5, pw)],
      s: rnd(0.1, 0.3),
      dir: nrm([rnd(-1,1), rnd(0.2,1), rnd(-1,1)]),
      va: rnd(-7, 7), life: rnd(0.7, 1.15), col: col
    });
  }
  if(SHARDS.length > 40){ SHARDS.splice(0, SHARDS.length - 40); }
}

function afterImage(f){
  if(FPS.low || !f.J){ return; }
  var J = {}, k;
  for(k in f.J){ J[k] = [f.J[k][0], f.J[k][1], f.J[k][2]]; }
  AFTER.push({ J: J, col: f.R.col, life: 0.45, l0: 0.45 });
  if(AFTER.length > 8){ AFTER.shift(); }
}

// ---- parametric normal factories ----
function mkPunch(o){
  var kind = o.kind || 'straight';
  return { d: o.d, name: o.name,
    wins: [{ a0: 0.34, a1: 0.62,
             tip: (o.side === 'L' ? 'haL' : 'haR'), dmg: o.dmg, kb: o.kb }],
    fn: function(f, t, p){
      var R = f.R, e, ex = (o.ext || 1)*R.scale;
      if(t < 0.34){ e = EO(t/0.34); }
      else if(t < 0.62){ e = 1; }
      else { e = 1 - EI((t-0.62)/0.38); }
      var S = (o.side === 'L') ? -1 : 1;
      var HA = (o.side === 'L') ? 'haL' : 'haR';
      var EL = (o.side === 'L') ? 'elL' : 'elR';
      var SH = (o.side === 'L') ? 'shL' : 'shR';
      var gu = [S*R.haX, R.haY, R.haZ];
      var hy = R.chY + (o.hy || 0.06);
      var tgt;
      if(kind === 'hook'){
        var wq = [S*(R.haX + 0.55), R.chY + 0.40, R.haZ - 0.12];
        var fin = [S*0.12, hy + 0.24, R.haZ + 0.92*ex];
        if(e < 0.55){ tgt = LZ(gu, wq, EO(e/0.55)); }
        else { tgt = LZ(wq, fin, EO((e-0.55)/0.45)); }
        p[EL] = [L(S*R.elX, S*0.62, e), L(R.elY, hy + 0.34, e), L(R.elZ, 0.45, e)];
      } else if(kind === 'overhead'){
        var up = [S*0.42, R.shY + 0.68, 0.10];
        var dn = [S*0.24, R.chY - 0.40, R.haZ + 0.88*ex];
        if(e < 0.5){ tgt = LZ(gu, up, EO(e/0.5)); }
        else { tgt = LZ(up, dn, EO((e-0.5)/0.5)); }
        p[EL] = [L(S*R.elX, S*0.50, e), L(R.elY, R.shY + 0.1, e), L(R.elZ, 0.28, e)];
      } else if(kind === 'slash'){
        var w0 = [-S*0.36, hy + 0.12, R.haZ - 0.06];
        var t1 = [S*0.20, hy, R.haZ + 1.02*ex];
        if(e < 0.42){ tgt = LZ(gu, w0, EO(e/0.42)); }
        else { tgt = LZ(w0, t1, EO((e-0.42)/0.58)); }
        p[EL] = [L(S*R.elX, -S*0.32, e), L(R.elY, hy + 0.10, e), L(R.elZ, 0.55, e)];
      } else {
        tgt = [S*0.15, hy, R.haZ + 1.08*ex];
        p[EL] = [L(S*R.elX, S*0.50, e), L(R.elY, hy + 0.10, e), L(R.elZ, 0.62, e)];
      }
      if(kind === 'straight'){ p[HA] = LZ(gu, tgt, e); }
      else { p[HA] = tgt; }
      p[SH] = [S*R.shX, R.shY, (kind === 'slash' ? -S*0.12 : S*0.16)*e];
      if(kind === 'slash'){
        p.pel[0] += -S*0.12*e; p.chs[0] += -S*0.06*e;
      } else {
        p.pel[0] += S*0.07*e;
      }
      var OH = (o.side === 'L') ? p.haR : p.haL;
      OH[1] += 0.06*e; OH[2] -= 0.08*e;
      if(kind === 'overhead'){ OH[1] += 0.30*e; }
    }};
}

function mkKick(o){
  var kind = o.kind || 'thrust';
  return { d: o.d, name: o.name,
    wins: [{ a0: 0.38, a1: 0.66, tip: 'ftR', dmg: o.dmg, kb: o.kb }],
    fn: function(f, t, p){
      var R = f.R, e;
      if(t < 0.38){ e = EO(t/0.38); }
      else if(t < 0.66){ e = 1; }
      else { e = 1 - EI((t-0.66)/0.34); }
      var ext = (o.ext || 1)*R.scale;
      var hy = (kind === 'low') ? 0.32 : R.chY + 0.16;
      p.ftR = [L(R.ftX, 0.16, e), L(0.10, hy, e), L(0.06, 1.12*ext, e)];
      p.knR = [L(R.knX, 0.24, e), L(R.knY, R.hipY + (kind === 'low' ? 0.16 : 0.34), e), L(R.knZ, 0.72, e)];
      p.hpR = [R.hpX - 0.06*e, R.hipY - 0.06, 0.12*e];
      p.chs[2] -= 0.14*e; p.uch[2] -= 0.14*e; p.hed[2] -= 0.12*e;
      if(kind === 'low'){ p.chs[1] -= 0.10*e; p.hed[2] += 0.24*e; }
      p.haL[2] += 0.14*e; p.haR[2] -= 0.08*e; p.haL[1] += 0.10*e;
    }};
}

var MOVE = {
  // ---- FSM state animations ----
  intro: { d: 1.1, wins: [], fn: function(f,t,p){
    var R = f.R, e = Math.sin(Math.min(1,t)*Math.PI);
    p.pel[1] -= 0.16*e;
    p.knL[1] -= 0.10*e; p.knR[1] -= 0.10*e;
    p.knL[2] += 0.10*e; p.knR[2] += 0.10*e;
    p.haL = [-R.shX-0.18, R.shY-0.05, 0.12];
    p.haR = [ R.shX+0.18, R.shY-0.05, 0.12];
    p.elL = [-R.shX-0.10, R.elY+0.20, 0.05];
    p.elR = [ R.shX+0.10, R.elY+0.20, 0.05];
    p.hed[1] += 0.04*e;
  }},
  hithigh: { d: 0.34, wins: [], fn: function(f,t,p){
    var e = EI(Math.min(1, t/0.10));
    if(t > 0.20){ e *= 1 - EZ((t-0.20)/0.14); }
    p.hed[2] -= 0.40*e; p.hed[1] += 0.07*e;
    p.chs[2] -= 0.22*e; p.uch[2] -= 0.20*e; p.chs[1] += 0.05*e;
    p.haL[2] -= 0.30*e; p.haR[2] -= 0.30*e;
    p.haL[1] += 0.18*e; p.haR[1] += 0.18*e;
  }},
  hitgut: { d: 0.38, wins: [], fn: function(f,t,p){
    var R = f.R;
    var e = EI(Math.min(1, t/0.10));
    if(t > 0.22){ e *= 1 - EZ((t-0.22)/0.16); }
    p.chs[2] += 0.24*e; p.chs[1] -= 0.16*e;
    p.uch[2] += 0.22*e; p.uch[1] -= 0.14*e;
    p.hed[2] += 0.32*e; p.hed[1] -= 0.30*e;
    p.haL = LZ(p.haL, [-0.24, R.chY-0.40, 0.42], e);
    p.haR = LZ(p.haR, [ 0.24, R.chY-0.42, 0.44], e);
  }},
  ko: { d: 1.5, wins: [], fn: function(f,t,p){
    var e = EO(Math.min(1, t/0.55));
    var LIE = {
      pel:[0,0.30,0], chs:[0,0.40,-0.30], uch:[0,0.46,-0.45], hed:[0,0.40,-0.90],
      shL:[-0.52,0.50,-0.38], shR:[0.52,0.50,-0.38],
      elL:[-0.72,0.28,-0.12], elR:[0.72,0.28,-0.08],
      haL:[-0.85,0.10,0.08], haR:[0.85,0.12,0.14],
      hpL:[-0.26,0.32,0], hpR:[0.26,0.32,0],
      knL:[-0.32,0.34,0.42], knR:[0.30,0.40,0.48],
      ftL:[-0.36,0.09,0.82], ftR:[0.36,0.10,0.88]
    };
    for(var k in LIE){ p[k] = LZ(p[k], LIE[k], e); }
    if(t > 0.45 && t < 0.62){
      var bb = Math.sin((t-0.45)/0.17*Math.PI)*0.06;
      p.pel[1] += bb; p.uch[1] += bb; p.hed[1] += bb;
    }
  }},
  victory: { d: 1.6, wins: [], fn: function(f,t,p){
    var R = f.R, s = Math.sin(t*Math.PI*2);
    p.haR = [0.42, R.shY + 0.55 + s*0.09, 0.10];
    p.elR = [0.60, R.shY + 0.18, 0.05];
    p.haL = [-R.haX, R.haY - 0.06, R.haZ - 0.08];
    p.hed[1] += 0.06; p.chs[2] -= 0.03;
  }},

  // ---- VANGUARD-01 : heroic boxing ----
  jab:  mkPunch({ side:'R', d:0.26, name:'JAB',       dmg:6,  kb:0.5,  kind:'straight' }),
  cross:mkPunch({ side:'L', d:0.34, name:'CROSS',     dmg:9,  kb:0.75, kind:'straight', ext:1.06 }),
  kick: mkKick({ d:0.42, name:'KICK', dmg:12, kb:1.1 }),

  // ---- GEAROX : heavy sledge boxing ----
  g_jab:   mkPunch({ side:'R', d:0.34, name:'HAMMER FIST', dmg:8,  kb:0.9,  kind:'straight', hy:0.12 }),
  g_cross: mkPunch({ side:'L', d:0.52, name:'SLEDGE BLOW',  dmg:13, kb:1.5,  kind:'overhead', ext:0.95 }),
  g_kick:  mkKick({ d:0.55, name:'PILE KICK', dmg:15, kb:1.7, ext:1.05 }),

  // ---- VERMIL : fast blade slashes ----
  v_jab:   mkPunch({ side:'R', d:0.22, name:'QUICK SLASH', dmg:5, kb:0.35, kind:'slash' }),
  v_cross: mkPunch({ side:'L', d:0.30, name:'RIPOSTE',     dmg:8, kb:0.55, kind:'slash', ext:1.10 }),
  v_kick:  mkKick({ d:0.36, name:'SWEEP CUT', dmg:10, kb:0.95, kind:'low' }),

  // ---- KOLOSS : piston power ----
  k_jab:   mkPunch({ side:'R', d:0.30, name:'PISTON JAB', dmg:7,  kb:0.9,  kind:'straight' }),
  k_cross: mkPunch({ side:'L', d:0.50, name:'ANVIL HOOK', dmg:13, kb:1.6,  kind:'hook' }),
  k_kick:  mkKick({ d:0.50, name:'RAM KICK', dmg:13, kb:1.9, ext:1.05 }),

  // ---- GHOST-9 : phase strikes ----
  gh_jab:   mkPunch({ side:'R', d:0.20, name:'PHASE JAB',   dmg:4, kb:0.35, kind:'straight' }),
  gh_cross: mkPunch({ side:'L', d:0.27, name:'PHANTOM CUT', dmg:7, kb:0.55, kind:'slash' }),
  gh_kick:  mkKick({ d:0.31, name:'DRIFT KICK', dmg:9, kb:0.95 }),

  // ---- EMBERFANG : savage claw chains ----
